<template><PageShell title="Reports & Analytics" subtitle="A compact operational summary based on your organization's real offers, missions, fleet, and personnel records." icon="lucide:chart-column" eyebrow="Organization Management"><div class="grid gap-3 sm:grid-cols-2 xl:grid-cols-5"><Stat label="Missions" :value="stats.missions_total"/><Stat label="Completed" :value="stats.completed"/><Stat label="Active" :value="stats.active"/><Stat label="Fleet available" :value="stats.fleet_available"/><Stat label="Personnel available" :value="stats.personnel_available"/></div><div class="mt-6 grid gap-6 lg:grid-cols-2"><section class="rounded-3xl border border-base-300 bg-base-100 p-5 shadow-sm dark:border-white/10 dark:bg-[#071829]"><h2 class="font-black dark:text-white">Offer performance</h2><div class="mt-4 grid grid-cols-3 gap-2 text-center"><Mini label="Accepted" :value="stats.offers_accepted"/><Mini label="Declined" :value="stats.offers_declined"/><Mini label="Timed out" :value="stats.offers_timed_out"/></div></section><section class="rounded-3xl border border-base-300 bg-base-100 p-5 shadow-sm dark:border-white/10 dark:bg-[#071829]"><h2 class="font-black dark:text-white">Response timing</h2><div class="mt-4 grid grid-cols-2 gap-3"><Mini label="Avg response" :value="performance.avg_response_minutes?`${performance.avg_response_minutes} min`:'Not enough data'"/><Mini label="Avg mission" :value="performance.avg_mission_minutes?`${performance.avg_mission_minutes} min`:'Not enough data'"/></div></section></div></PageShell></template>
<script setup>import{defineComponent,h,onMounted,ref}from'vue';import PageShell from '@/components/management/PageShell.vue';import{fetchOrganizationReports}from'@/services/organizationCompletion';const stats=ref({}),performance=ref({});const Stat=defineComponent({props:{label:String,value:[String,Number]},setup:p=>()=>h('article',{class:'rounded-3xl border border-base-300 bg-base-100 p-5 shadow-sm dark:border-white/10 dark:bg-[#071829]'},[h('p',{class:'text-2xl font-black dark:text-white'},String(p.value??0)),h('p',{class:'mt-1 text-xs font-bold text-slate-500'},p.label)])});const Mini=defineComponent({props:{label:String,value:[String,Number]},setup:p=>()=>h('div',{class:'rounded-2xl bg-base-200 p-4'},[h('p',{class:'text-lg font-black dark:text-white'},String(p.value??0)),h('p',{class:'mt-1 text-xs font-bold text-slate-500'},p.label)])});onMounted(async()=>{const d=await fetchOrganizationReports();stats.value=d.stats||{};performance.value=d.performance||{}})</script>
